--
-- Name: lastinsertproduct(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION lastinsertproduct(chaine text) RETURNS TABLE(a integer, b character varying)
    LANGUAGE plpgsql
    AS $$

begin

CREATE TEMP TABLE tblp (id int not null,ref character varying)on commit drop;


                 FROM  llx_product 

                 WHERE ref =  ANY (string_to_array(chaine, ','))

	         ORDER BY ref);

   RETURN QUERY SELECT * FROM tblp;

return;

end;

$$;


ALTER FUNCTION public.lastinsertproduct(chaine text) OWNER TO postgres;

