    SELECT f.datef, f.facnumber, f.rowid AS fid, s.rowid AS sid, s.nom, f.fk_statut FROM llx_facture f, llx_societe s WHERE ((f.fk_soc = s.rowid) AND (NOT (f.rowid IN (SELECT llx_element_element.fk_target FROM llx_element_element WHERE (((llx_element_element.targettype)::text = 'facture'::text) OR ((llx_element_element.targettype)::text = 'facture_proforma'::text)))))) ORDER BY s.nom;


