--
-- Name: familleproduit; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW familleproduit AS
    SELECT p.rowid AS prodid, cp.fk_product AS categ, c.label AS labelcateg, fp.rowid AS famille, fp.label AS labelfamille, cu.rowid AS unite, cu.label AS labelunite, p.ref AS refprod, p.label AS labelprod, p.fk_product_type, p.weight, p.weight_units, p.volume, p.volume_units FROM (((((llx_product p LEFT JOIN llx_categorie_product cp ON ((p.rowid = cp.fk_product))) LEFT JOIN llx_famille_categorie fc ON ((fc.fk_categorie = cp.fk_categorie))) LEFT JOIN llx_categorie c ON ((c.rowid = cp.fk_categorie))) LEFT JOIN llx_famille_product fp ON ((fp.rowid = fc.fk_famille))) LEFT JOIN llx_c_unitemesure cu ON ((cu.rowid = fp.unite))) WHERE (p.envente = 1) ORDER BY p.rowid;


