-- Name: ls_bot_stk_lot_poids; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW ls_bot_stk_lot_poids AS
    SELECT prod2.ref, prod2.label, prod.form_num_lot, count(0) AS nbbottes, sum(prod.weight) AS poidslot FROM llx_product prod, llx_product prod2 WHERE (((prod.type_prod = 3) AND (prod2.rowid = (prod.id_form_nb_bot)::integer)) AND (prod.stock = 1)) GROUP BY prod2.ref, prod2.label, prod.form_num_lot;


