    SELECT cd.fk_product, sum(cd.qty) AS qtycmd FROM llx_commandedet cd, llx_commande c WHERE ((cd.fk_commande = c.rowid) AND (c.fk_statut = 1)) GROUP BY cd.fk_product;


ALTER TABLE public.produitcmd OWNER TO postgres;

--
-- Name: produitfini; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW produitfini AS
    SELECT p.rowid, p.ref, p.label, p.seuil_stock_alerte, p.weight_units, p.envente, c.rowid AS idcateg, c.label AS labelcateg, fp.rowid AS idfam, fp.label AS labelfam FROM ((((llx_product p LEFT JOIN llx_categorie_product cp ON ((cp.fk_product = p.rowid))) LEFT JOIN llx_categorie c ON ((cp.fk_categorie = c.rowid))) LEFT JOIN llx_famille_categorie fc ON ((cp.fk_categorie = fc.fk_categorie))) LEFT JOIN llx_famille_product fp ON ((fc.fk_famille = fp.rowid)));


ALTER TABLE public.produitfini OWNER TO postgres;

--
-- Name: produitsemifini; Type: VIEW; Schema: public; Owner: postgres
