CREATE VIEW produitsemifini AS
    SELECT p.rowid, p.ref, p.label, p.seuil_stock_alerte, p.weight_units, p.envente, c.rowid AS idcateg, c.label AS labelcateg, fp.rowid AS idfam, fp.label AS labelfam FROM llx_product p, llx_categorie_product cp, llx_categorie c, llx_famille_categorie fc, llx_famille_product fp WHERE (((((p.type_prod <> 3) AND (cp.fk_product = p.rowid)) AND (cp.fk_categorie = c.rowid)) AND (cp.fk_categorie = fc.fk_categorie)) AND (fc.fk_famille = fp.rowid));


ALTER TABLE public.produitsemifini OWNER TO postgres;

--
-- Name: rapportvisite; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW rapportvisite AS
    SELECT vr.rowid AS linerap, vr.fk_pdv AS idpdv, vr.fk_visite AS idvisite, vr.fk_product AS idproduct, vr.datec AS daterap, vr.mvt_art AS linedispo, vr.emp_prod AS lineplace, vr.pre_prix AS linepri, vr.art_prom AS linepromocomq, vr.reclamation AS posipromo, pdv.ref AS refpdv, pdv.nom AS nompdv, pdv.fk_client AS idclient, pdv.region, pdv.fk_gov AS gov, pdv.fk_user_comm AS commercial, vp.fk_user_author AS createurvisite, vp.fk_user_done AS donevisite, vp.datecreel AS datecvisite, vp.datec AS datevisite, vp.fk_status AS statusvisite, vp.commantaire, vp.date_valid, vp.fk_user_valid AS validateurvisite, p.ref AS refproduct, p.label AS labelproduct, s.nom, u.name AS nomcommercial, reg.deleg, reg.fk_gouv AS idgov, reg.gouvernorat, emp.code AS codeemp, pro.code AS codepro FROM ((((((((llx_pointvente_rapport vr LEFT JOIN llx_pointvente pdv ON ((pdv.rowid = vr.fk_pdv))) LEFT JOIN llx_visite_pointevente vp ON ((vp.rowid = vr.fk_visite))) LEFT JOIN llx_product p ON ((p.rowid = vr.fk_product))) LEFT JOIN llx_societe s ON ((s.rowid = pdv.fk_client))) LEFT JOIN llx_user u ON ((u.rowid = vp.fk_user_done))) LEFT JOIN llx_c_regions reg ON ((reg.rowid = pdv.region))) LEFT JOIN llx_c_emplacementproduit emp ON (((emp.rowid)::text = (vr.emp_prod)::text))) LEFT JOIN llx_c_produitpromotion pro ON (((pro.rowid)::text = (vr.reclamation)::text)));


ALTER TABLE public.rapportvisite OWNER TO postgres;

--
-- Name: rapportvisites; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW rapportvisites AS
    SELECT vr.rowid AS linerap, vr.fk_pdv AS idpdv, vr.fk_visite AS idvisite, vr.fk_product AS idproduct, vr.datec AS daterap, vr.mvt_art AS linedispo, vr.emp_prod AS lineplace, vr.pre_prix AS linepri, vr.art_prom AS linepromocomq, vr.reclamation AS posipromo, pdv.ref AS refpdv, pdv.nom AS nompdv, pdv.fk_client AS idclient, pdv.region, pdv.fk_gov AS gov, pdv.fk_user_comm AS commercial, vp.fk_user_author AS createurvisite, vp.fk_user_done AS donevisite, vp.datecreel AS datecvisite, vp.datec AS datevisite, vp.fk_status AS statusvisite, vp.commantaire, vp.date_valid, vp.fk_user_valid AS validateurvisite, p.ref AS refproduct, p.label AS labelproduct, s.nom, u.name AS nomcommercial, reg.deleg, reg.fk_gouv AS idgov, reg.gouvernorat FROM ((((((llx_pointvente_rapport vr LEFT JOIN llx_pointvente pdv ON ((pdv.rowid = vr.fk_pdv))) LEFT JOIN llx_visite_pointevente vp ON ((vp.rowid = vr.fk_visite))) LEFT JOIN llx_product p ON ((p.rowid = vr.fk_product))) LEFT JOIN llx_societe s ON ((s.rowid = pdv.fk_client))) LEFT JOIN llx_user u ON ((u.rowid = vp.fk_user_done))) LEFT JOIN llx_c_regions reg ON ((reg.rowid = pdv.region)));


